/** Что оставлено VKUI: [шаблон имени, почему]. */
export const left: ReadonlyArray<readonly [RegExp, string]> = [
  [new RegExp("^--vkui--size_(button_(extra_small|small|medium|large)_height|button_minimum_width|field_height|search_height|cell_height|panel_header_height|popup_(small|medium|large)|switch_|checkbox|avatar_|badge_|arrow--|arrow_promo|icon_u_i|option_hierarchy)"), "размер детали VKUI (высота кнопки, поля, шапки; ширина окна; аватар, значок): у Carbon для этих мест токена нет, высоты меняются отдельным решением вместе с экранами"],
  [new RegExp("^--vkui--size_border(1x|2x|3x)?--"), "толщина линии под плотность экрана (1px, 0,5px) — у Carbon токена нет"],
  [new RegExp("^--vkui--size_button_group_gap_space--"), "стык кнопок в группе (1px) — толщина линии, не отступ"],
  [new RegExp("^--vkui--opacity_"), "прозрачность выключенного и нажатого — у Carbon токена нет (у него свои цвета выключенного)"],
  [new RegExp("^--vkui--z_index_"), "порядок слоёв окна — не облик"],
  [new RegExp("^--vkui--colors_scheme$"), "слово light или dark для color-scheme — ставит сам VKUI по теме"],
  [new RegExp("^--vkui--(gradient|blur_)"), "градиент из нескольких точек и размытие фона — у Carbon таких токенов нет"],
  [new RegExp("^--vkui--theme_"), "служебное имя темы VKUI"],
  [new RegExp("^--vkui--font_\\w+--text_transform--"), "ПРОПИСНЫЕ у подписей _caps — правило набора VKUI, не токен"],
]

/** Строка CSS для токена Carbon. */
export function cssValue(token: string): string {
  if (token === 'transparent') return 'transparent'
  const lh = /^(.+)-line-height$/.exec(token)
  if (lh) return `calc(var(--cds-${lh[1]}-font-size) * var(--cds-${token}))`
  return `var(--cds-${token})`
}

/** Чем закрыта переменная VKUI: 'carbon' — токеном (в обеих темах), 'vkui' — оставлена VKUI с причиной, null — ничем. */
export function coverage(name: string): 'carbon' | 'vkui' | null {
  if (name in common || (name in colors.light && name in colors.dark)) return 'carbon'
  if (left.some(([re]) => re.test(name))) return 'vkui'
  return null
}
